window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ab84a76f16485d1f"]={"versions": [{"id": "FIG-ab84a76f16485d1f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-/Header-Layout mit 32-Bit-Raster). Das Diagramm spezifiziert das standardisierte On-Wire-Nachrichtenformat des SOME/IP-Headers (Scalable service-Oriented MiddlewarE over IP) im AUTOSAR-Transformator-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte Bitfelder innerhalb eines 32-Bit-Breitenrasters (Bit-Offset 0 bis 31):</p>\n<ul class=\"fig-list\">\n<li><code>Message ID (Service ID / Method ID)</code> [32 bit]</li>\n<li><code>Length</code> [32 bit]</li>\n<li><code>Request ID (Client ID / Session ID)</code> [32 bit]</li>\n<li><code>Protocol Version</code> [8 bit] (Bits 0–7)</li>\n<li><code>Interface Version</code> [8 bit] (Bits 8–15)</li>\n<li><code>Message Type</code> [8 bit] (Bits 16–23)</li>\n<li><code>Return Code</code> [8 bit] (Bits 24–31)</li>\n<li><code>Payload</code> [variable size]</li>\n</ul>\n<p class=\"fig-p\">Ein vertikaler Maßpfeil an der rechten Seite kennzeichnet den Bereich <code>Covered by Length</code>, der sich von der <code>Request ID</code> über die 8-Bit-Headerfelder bis einschließlich zur <code>Payload</code> erstreckt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsstruktur bei der Übertragung von Service-Oriented-Nachrichten. Der Header wird sequenziell von MSB/Offset 0 in 32-Bit-Wörtern übertragen: Zunächst Message ID und Längenfeld, gefolgt vom Nutzlastblock (Request ID, Versions- und Typfelder sowie eigentliche Payload). Die Übertragungslänge im Feld <code>Length</code> quantifiziert dynamisch alle nachfolgenden Bytes ab Byte-Offset 8 bis zum Ende der Payload.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der SOME/IP-Serialisierung auf Feldebene. Gemäß SWS_SomeIpXf_00015 implementiert der SOME/IP-Transformer lediglich den unteren Header-Teil ab <code>Request ID</code> sowie die <code>Payload</code>; <code>Message ID</code> und <code>Length</code> werden von übergeordneten bzw. nachgelagerten BSW-Modulen ergänzt. Das Feld <code>Length</code> darf die vorausgehenden 8 Bytes (<code>Message ID</code>, <code>Length</code>) nicht mitzählen. Alle Multi-Byte-Felder folgen der SOME/IP-Endianness-Vorgabe (Big-Endian/Network Byte Order).</p>"}, {"id": "FIG-de286f8c374d90e0", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-/Header-Layout mit 32-Bit-Raster). Das Diagramm spezifiziert das standardisierte On-Wire-Nachrichtenformat des SOME/IP-Headers (Scalable service-Oriented MiddlewarE over IP) im AUTOSAR-Transformator-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte Bitfelder innerhalb eines 32-Bit-Breitenrasters (Bit-Offset 0 bis 31):</p>\n<ul class=\"fig-list\">\n<li><code>Message ID (Service ID / Method ID)</code> [32 bit]</li>\n<li><code>Length</code> [32 bit]</li>\n<li><code>Request ID (Client ID / Session ID)</code> [32 bit]</li>\n<li><code>Protocol Version</code> [8 bit] (Bits 0–7)</li>\n<li><code>Interface Version</code> [8 bit] (Bits 8–15)</li>\n<li><code>Message Type</code> [8 bit] (Bits 16–23)</li>\n<li><code>Return Code</code> [8 bit] (Bits 24–31)</li>\n<li><code>Payload</code> [variable size]</li>\n</ul>\n<p class=\"fig-p\">Ein vertikaler Maßpfeil an der rechten Seite kennzeichnet den Bereich <code>Covered by Length</code>, der sich von der <code>Request ID</code> über die 8-Bit-Headerfelder bis einschließlich zur <code>Payload</code> erstreckt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Serialisierungsstruktur bei der Übertragung von Service-Oriented-Nachrichten. Der Header wird sequenziell von MSB/Offset 0 in 32-Bit-Wörtern übertragen: Zunächst Message ID und Längenfeld, gefolgt vom Nutzlastblock (Request ID, Versions- und Typfelder sowie eigentliche Payload). Die Übertragungslänge im Feld <code>Length</code> quantifiziert dynamisch alle nachfolgenden Bytes ab Byte-Offset 8 bis zum Ende der Payload.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der SOME/IP-Serialisierung auf Feldebene. Gemäß SWS_SomeIpXf_00015 implementiert der SOME/IP-Transformer lediglich den unteren Header-Teil ab <code>Request ID</code> sowie die <code>Payload</code>; <code>Message ID</code> und <code>Length</code> werden von übergeordneten bzw. nachgelagerten BSW-Modulen ergänzt. Das Feld <code>Length</code> darf die vorausgehenden 8 Bytes (<code>Message ID</code>, <code>Length</code>) nicht mitzählen. Alle Multi-Byte-Felder folgen der SOME/IP-Endianness-Vorgabe (Big-Endian/Network Byte Order).</p>"}], "trans": [{"from": "FIG-ab84a76f16485d1f", "to": "FIG-de286f8c374d90e0", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
